# Keep the Thread radio powered in standby on an installed (switchable) border router. Without this the radio loses
# power when the TV goes to standby: Samsung's iot-hub-control switches the module off, and storaged powers the USB
# ports down. Blocks iot-hub-control and adds the USB power keeper unit. Feed to /bin/sh on stdin as root.
# Inverse: otbr-standby-restore.sh.
set -eu
H=/opt/usr/home/owner; UD=$H/.config/systemd/user; Q=/opt/usr/share/quiet-otbr
usr(){ env HOME=$H XDG_RUNTIME_DIR=/run/user/5001 DBUS_SESSION_BUS_ADDRESS=kernel:path=/sys/fs/kdbus/5001-user/bus systemctl --user "$@"; }
[ "$(id -u)" = 0 ]
[ -e "$UD/quiet-otbr-switch.path" ] || { echo "switchable border router not installed (otbr-install.sh / otbr-switch-update.sh first)"; exit 3; }
[ ! -e "$UD/quiet-otbr-usbpower.service" ] || { echo "keeper already installed"; exit 3; }
LBL=$(chsmack $H | sed 's/.*access="//; s/".*//')
B=/opt/usr/share/quiet-tizen-backups/thread-border-router; mkdir -p "$B/units-before-usbpower"; chmod 700 "$B"
cp -a "$UD/quiet-otbr-switch.service" "$B/units-before-usbpower/"
# Samsung's iot-hub-control (started on demand through its IHubControl RPC port) switches the radio module off when the
# TV enters standby while the SmartThings hub is off. Blocked in the app registry (same lever as the privacy batches);
# the inverse re-enables it.
DB=/opt/dbspace/.pkgmgr_parser.db
if [ "$(sqlite3 -readonly $DB "select app_disable from package_app_info where app_id='com.samsung.tv.iot-hub-control'")" = false ]; then
  mkdir -p "$B"; [ -e "$B/registry-before-ihc.db" ] || cp -a $DB "$B/registry-before-ihc.db"
  sqlite3 -bail $DB "BEGIN IMMEDIATE; UPDATE package_app_info SET app_disable='true' WHERE app_id='com.samsung.tv.iot-hub-control' AND app_disable='false'; COMMIT;"
  [ "$(sqlite3 -readonly $DB 'PRAGMA quick_check;')" = ok ]
  touch "$B/ihc-disabled-by-quiet-otbr"
  /usr/bin/dotnet /opt/usr/share/quiet-tizen-backups/privacy-phaseB-20261024T135601/AppMetadata.dll reload-owner >/dev/null 2>&1 || true
  P=$(pgrep -f /bin/iot-hub-control | head -n1); [ -n "$P" ] && kill $P || true
fi
base64 -d > "$Q/quiet-otbr-usbpower.dll.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$Q/quiet-otbr-usbpower.dll.new" | cut -d" " -f1)" = afd98e2b38b78f9f868e36f280b2fbad441b6a827936edecbec743618b92836e ]
chown root:users "$Q/quiet-otbr-usbpower.dll.new"; chmod 644 "$Q/quiet-otbr-usbpower.dll.new"; chsmack -a User "$Q/quiet-otbr-usbpower.dll.new"; mv "$Q/quiet-otbr-usbpower.dll.new" "$Q/quiet-otbr-usbpower.dll"
base64 -d > "$Q/quiet-otbr-usbpower.runtimeconfig.json.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$Q/quiet-otbr-usbpower.runtimeconfig.json.new" | cut -d" " -f1)" = a0882085ebc8618322fb819cc0e92bac0499419af91124d05f6d27662818ea83 ]
chown root:users "$Q/quiet-otbr-usbpower.runtimeconfig.json.new"; chmod 644 "$Q/quiet-otbr-usbpower.runtimeconfig.json.new"; chsmack -a User "$Q/quiet-otbr-usbpower.runtimeconfig.json.new"; mv "$Q/quiet-otbr-usbpower.runtimeconfig.json.new" "$Q/quiet-otbr-usbpower.runtimeconfig.json"
base64 -d > "$UD/quiet-otbr-usbpower.service.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$UD/quiet-otbr-usbpower.service.new" | cut -d" " -f1)" = 3445f996edca9f28631c2958d110661700888a3749c77e53f2199b9504b3184f ]
chown owner:users "$UD/quiet-otbr-usbpower.service.new"; chmod 644 "$UD/quiet-otbr-usbpower.service.new"; chsmack -a "$LBL" "$UD/quiet-otbr-usbpower.service.new"; mv "$UD/quiet-otbr-usbpower.service.new" "$UD/quiet-otbr-usbpower.service"
ln -sf ../quiet-otbr-usbpower.service "$UD/default.target.wants/quiet-otbr-usbpower.service"; chown -h owner:users "$UD/default.target.wants/quiet-otbr-usbpower.service"
base64 -d > "$UD/quiet-otbr-switch.service.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$UD/quiet-otbr-switch.service.new" | cut -d" " -f1)" = ed643c450b6bbb15f5f4727e57957d871312cb190d54fffe2082d0174c131953 ]
chown owner:users "$UD/quiet-otbr-switch.service.new"; chmod 644 "$UD/quiet-otbr-switch.service.new"; chsmack -a "$LBL" "$UD/quiet-otbr-switch.service.new"; mv "$UD/quiet-otbr-switch.service.new" "$UD/quiet-otbr-switch.service"
usr daemon-reload
usr start --no-block quiet-otbr-usbpower.service
sleep 8
echo "quiet-otbr-usbpower: $(usr is-enabled quiet-otbr-usbpower.service) $(usr is-active quiet-otbr-usbpower.service)"
grep usbpower /run/user/5001/quiet-otbr.log | tail -n 2
echo "STANDBY POWER INSTALLED (iot-hub-control blocked, keeper running)"
